export const isMain = (s: SetupState): s is MainState => (MAIN_FLOW as readonly string[]).includes(s)
export const inMode = (s: MainState, mode: SetupMode) => SPECS[s].modes.includes(mode)
export const flowFor = (mode: SetupMode): MainState[] => MAIN_FLOW.filter((s) => inMode(s, mode))
